-- Generated by scripts/generate-occupation-category.mjs from category_rules.json.
-- 2026-10-22 Lee: derive the existing app category from the official occupation code.
-- No occupation/evidence/publication rule changes; no new data access or SECURITY DEFINER.
create or replace function public.category_for_occupation(p_code text)
returns text language sql stable security invoker set search_path = '' as $$
  select coalesce((select case
      when m.code like '2431%' then 'truyen_thong'
      when m.code like '2432%' then 'truyen_thong'
      when m.code like '2641%' then 'truyen_thong'
      when m.code like '2642%' then 'truyen_thong'
      when m.code like '2651%' then 'thiet_ke'
      when m.code like '3431%' then 'truyen_thong'
      when m.code like '3432%' then 'thiet_ke'
      when m.code like '3433%' then 'van_phong'
      when m.code like '3434%' then 'am_thuc_do_uong'
      when m.code like '3521%' then 'truyen_thong'
      when m.code like '4221%' then 'dich_vu'
      when m.code like '4224%' then 'dich_vu'
      when m.code like '4227%' then 'van_phong'
      when m.code like '5311%' then 'dich_vu'
      when m.code like '5312%' then 'giao_duc_giang_day'
      when m.code like '9331%' then 'lai_xe_giao_hang'
      when m.code like '9332%' then 'lai_xe_giao_hang'
      when m.code like '9334%' then 'quan_ly_ban_hang'
      when m.code like '9621%' then 'lai_xe_giao_hang'
      when m.code like '211%' then 'y_te_dieu_duong'
      when m.code like '212%' then 'y_te_dieu_duong'
      when m.code like '213%' then 'y_te_dieu_duong'
      when m.code like '216%' then 'thiet_ke'
      when m.code like '243%' then 'cskh_kinh_doanh'
      when m.code like '265%' then 'truyen_thong'
      when m.code like '312%' then 'san_xuat_xay_dung'
      when m.code like '314%' then 'y_te_dieu_duong'
      when m.code like '332%' then 'cskh_kinh_doanh'
      when m.code like '333%' then 'cskh_kinh_doanh'
      when m.code like '421%' then 'van_phong'
      when m.code like '512%' then 'am_thuc_do_uong'
      when m.code like '513%' then 'am_thuc_do_uong'
      when m.code like '831%' then 'lai_xe_giao_hang'
      when m.code like '832%' then 'lai_xe_giao_hang'
      when m.code like '833%' then 'lai_xe_giao_hang'
      when m.code like '835%' then 'lai_xe_giao_hang'
      when m.code like '951%' then 'dich_vu'
      when m.code like '21%' then 'cntt_ky_thuat'
      when m.code like '22%' then 'y_te_dieu_duong'
      when m.code like '23%' then 'giao_duc_giang_day'
      when m.code like '24%' then 'van_phong'
      when m.code like '25%' then 'cntt_ky_thuat'
      when m.code like '26%' then 'van_phong'
      when m.code like '31%' then 'cntt_ky_thuat'
      when m.code like '32%' then 'y_te_dieu_duong'
      when m.code like '33%' then 'van_phong'
      when m.code like '34%' then 'dich_vu'
      when m.code like '35%' then 'cntt_ky_thuat'
      when m.code like '36%' then 'giao_duc_giang_day'
      when m.code like '42%' then 'cskh_kinh_doanh'
      when m.code like '52%' then 'quan_ly_ban_hang'
      when m.code like '53%' then 'y_te_dieu_duong'
      when m.code like '91%' then 'dich_vu'
      when m.code like '92%' then 'san_xuat_xay_dung'
      when m.code like '93%' then 'san_xuat_xay_dung'
      when m.code like '94%' then 'am_thuc_do_uong'
      when m.code like '95%' then 'quan_ly_ban_hang'
      when m.code like '96%' then 'dich_vu'
      when m.code like '0%' then 'khac'
      when m.code like '1%' then 'khac'
      when m.code like '2%' then 'khac'
      when m.code like '3%' then 'khac'
      when m.code like '4%' then 'van_phong'
      when m.code like '5%' then 'dich_vu'
      when m.code like '6%' then 'san_xuat_xay_dung'
      when m.code like '7%' then 'san_xuat_xay_dung'
      when m.code like '8%' then 'san_xuat_xay_dung'
      when m.code like '9%' then 'khac'
      else 'khac' end from public.occupation_master m where m.code = p_code), 'khac');
$$;
revoke all on function public.category_for_occupation(text) from public;
grant execute on function public.category_for_occupation(text) to anon,authenticated,service_role;

create or replace function public.sync_occupation_category()
returns trigger language plpgsql security invoker set search_path = '' as $$
begin
  new.category := public.category_for_occupation(new.occupation_code);
  return new;
end;
$$;
revoke all on function public.sync_occupation_category() from public;
-- Before policy evaluation; then again after R8 may clear an obsolete occupation/evidence.
create trigger trg_00_occupation_category before insert or update on public.local_jobs
for each row execute function public.sync_occupation_category();
create trigger trg_zzzy_occupation_category before insert or update on public.local_jobs
for each row execute function public.sync_occupation_category();

-- Only already classified rows with inconsistent categories. Production dry-run found zero.
update public.local_jobs set category=public.category_for_occupation(occupation_code)
where occupation_code is not null and category is distinct from public.category_for_occupation(occupation_code);
comment on function public.category_for_occupation(text) is
'QĐ34/2020 official occupation code to existing Viecganban menu category; longest prefix. Broad mixed groups use khac. No deeper occupation is inferred.';
